mapper.select:
SELECT t.TODO_ID, t.OWNER_USER_ID, t.TITLE, t.DESCRIPTION, t.PRIORITY, t.DUE_DATE, t.DUE_TIME, t.IS_COMPLETED, t.COMPLETED_AT, t.SORT_ORDER, t.REPEAT_TYPE, t.REPEAT_INTERVAL, t.REPEAT_DAYS, t.REPEAT_END_DATE, t.NEXT_DUE_DATE, t.PARENT_TODO_ID, t.TRANSFERRED_FROM_USER_ID, t.TRANSFERRED_AT, t.USE_YN, t.CREATED_AT, t.CREATED_BY, t.UPDATED_AT, t.UPDATED_BY, u.NAME AS OWNER_USER_NAME, u.USERNAME AS OWNER_USERNAME, tf.NAME AS TRANSFERRED_FROM_USER_NAME, (SELECT COUNT(*) FROM TB_TODO_SHARE WHERE TODO_ID = t.TODO_ID) AS SHARE_COUNT FROM TB_TODO t INNER JOIN TB_USER u ON t.OWNER_USER_ID = u.USER_ID LEFT JOIN TB_USER tf ON t.TRANSFERRED_FROM_USER_ID = tf.USER_ID WHERE t.OWNER_USER_ID = #{ownerUserId} AND t.USE_YN = 'Y'
AND t.IS_COMPLETED = FALSE
AND t.DUE_DATE >= #{dueDateFrom}
AND t.DUE_DATE <= #{dueDateTo}
ORDER BY t.SORT_ORDER ASC, t.DUE_DATE ASC, t.CREATED_AT DESC

SELECT t.TODO_ID, t.OWNER_USER_ID, t.TITLE, t.DESCRIPTION, t.PRIORITY, t.DUE_DATE, t.DUE_TIME, t.IS_COMPLETED, t.COMPLETED_AT, t.SORT_ORDER, t.REPEAT_TYPE, t.CREATED_AT, t.CREATED_BY, u.NAME AS OWNER_USER_NAME FROM TB_TODO t INNER JOIN TB_USER u ON t.OWNER_USER_ID = u.USER_ID WHERE t.OWNER_USER_ID = #{ownerUserId} AND t.USE_YN = 'Y' AND t.IS_COMPLETED = TRUE
AND DATE(t.COMPLETED_AT) >= #{completedDateFrom}
AND DATE(t.COMPLETED_AT) <= #{completedDateTo}
ORDER BY t.COMPLETED_AT DESC

mapper.update:
UPDATE TB_TODO
SET SORT_ORDER = #{sortOrder},
    UPDATED_AT = NOW(),
    UPDATED_BY = #{updatedBy}
WHERE TODO_ID = #{todoId}

UPDATE TB_TODO
SET USE_YN = #{useYn},
    UPDATED_AT = NOW(),
    UPDATED_BY = #{updatedBy}
WHERE TODO_ID = #{todoId}

UPDATE TB_TODO
SET USE_YN = #{useYn},
    UPDATED_AT = NOW(),
    UPDATED_BY = #{updatedBy}
WHERE OWNER_USER_ID = #{ownerUserId}

UPDATE TB_TODO
SET NEXT_DUE_DATE = #{nextDueDate},
    UPDATED_AT = NOW(),
    UPDATED_BY = #{updatedBy}
WHERE TODO_ID = #{todoId}
